CREATE TABLE v (c TEXT, n INTEGER, x INTEGER);
INSERT INTO v VALUES ('r',1,4),('r',2,7),('r',3,1),('r',4,8),('s',1,2),('s',2,9);
SELECT c, n, sum(x) OVER (pc ORDER BY n ROWS 1 PRECEDING), sum(x) OVER (pc ORDER BY n RANGE BETWEEN CURRENT ROW AND 1 FOLLOWING) FROM v WINDOW pc AS (PARTITION BY c) ORDER BY c, n;
SELECT c, n, first_value(x) OVER (pc ORDER BY x DESC), row_number() OVER (pc ORDER BY x) FROM v WINDOW pc AS (PARTITION BY c) ORDER BY c, n;
SELECT n, sum(x) OVER (ww ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) FROM v WHERE c = 'r' WINDOW ww AS (ORDER BY n) ORDER BY n;
SELECT n, group_concat(x, ' ') OVER (e ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) FROM v WINDOW e AS (PARTITION BY c ORDER BY n DESC) ORDER BY c, n;
SELECT n, count(*) OVER (base) FROM v WINDOW base AS (PARTITION BY c) ORDER BY c, n;
